Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
Bluetooth: L2CAP: Fix ERTM re-init and zero pdu_len infinite
 loop

l2cap_config_req() processes CONFIG_REQ for channels in BT_CONNECTED
state to support L2CAP reconfiguration (e.g. MTU changes). However,
since both CONF_INPUT_DONE and CONF_OUTPUT_DONE are already set from
the initial configuration, the reconfiguration path falls through to
l2cap_ertm_init(), which re-initializes tx_q, srej_q, srej_list, and
retrans_list without freeing the previous allocations and sets
chan->sdu to NULL without freeing the existing skb. This leaks all
previously allocated ERTM resources.

Additionally, l2cap_parse_conf_req() does not validate the minimum
value of remote_mps derived from the RFC max_pdu_size option. A zero
value propagates to l2cap_segment_sdu() where pdu_len becomes zero,
causing the while loop to never terminate since len is never
decremented, exhausting all available memory.

Fix the double-init by skipping l2cap_ertm_init() and
l2cap_chan_ready() when the channel is already in BT_CONNECTED state,
while still allowing the reconfiguration parameters to be updated
through l2cap_parse_conf_req(). Also add a pdu_len zero check in
l2cap_segment_sdu() as a safeguard.

Fixes: 96298f640104 ("Bluetooth: L2CAP: handle l2cap config request during open state")
Signed-off-by: Hyunwoo Kim <imv4bel@gmail.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
In l2cap_config_req(), when processing CONFIG_REQ for channels already in BT_CONNECTED state, the code unconditionally re-initializes ERTM data structures (l2cap_ertm_init()) without freeing previous allocations, causing memory leaks and setting chan->sdu to NULL. Additionally, l2cap_parse_conf_req() does not validate the minimum value of remote_mps derived from the max_pdu_size option, allowing zero pdu_len which leads to infinite loop in l2cap_segment_sdu().

Here is the patch:

 static int l2cap_segment_sdu(struct l2cap_chan *chan,
 			     struct sk_buff_head *seg_queue,
 			     struct msghdr *msg, size_t len)
 {
 	struct sk_buff *skb;
 	u16 sdu_len;
 	size_t pdu_len;
 	u8 sar;

 	BT_DBG("chan %p, msg %p, len %zu", chan, msg, len);

 	/* It is critical that ERTM PDUs fit in a single HCI fragment,
 	 * so fragmented skbs are not used.  The HCI layer's handling
 	 * of fragmented skbs is not compatible with ERTM's queueing.
 	 */

 	/* PDU size is derived from the HCI MTU */
 	pdu_len = chan->conn->mtu;

 	/* Constrain PDU size for BR/EDR connections */
 	pdu_len = min_t(size_t, pdu_len, L2CAP_BREDR_MAX_PAYLOAD);

 	/* Adjust for largest possible L2CAP overhead. */
 	if (chan->fcs)
 		pdu_len -= L2CAP_FCS_SIZE;

 	pdu_len -= __ertm_hdr_size(chan);

 	/* Remote device may have requested smaller PDUs */
 	pdu_len = min_t(size_t, pdu_len, chan->remote_mps);

+	if (!pdu_len)
+		return -EINVAL;
+
 	if (len <= pdu_len) {
 		sar = L2CAP_SAR_UNSEGMENTED;
 		sdu_len = 0;
 		pdu_len = len;
 	} else {
 		sar = L2CAP_SAR_START;
 		sdu_len = len;
 	}

 	while (len > 0) {
 		skb = l2cap_create_iframe_pdu(chan, msg, pdu_len, sdu_len);

 		if (IS_ERR(skb)) {
 			__skb_queue_purge(seg_queue);
 			return PTR_ERR(skb);
 		}

 		bt_cb(skb)->l2cap.sar = sar;
 		__skb_queue_tail(seg_queue, skb);

 		len -= pdu_len;
 		if (sdu_len)
 			sdu_len = 0;

 		if (len <= pdu_len) {
 			sar = L2CAP_SAR_END;
 			pdu_len = len;
 		} else {
 			sar = L2CAP_SAR_CONTINUE;
 		}
 	}

 	return 0;
 }


 static inline int l2cap_config_req(struct l2cap_conn *conn,
 				   struct l2cap_cmd_hdr *cmd, u16 cmd_len,
 				   u8 *data)
 {
 	struct l2cap_conf_req *req = (struct l2cap_conf_req *) data;
 	u16 dcid, flags;
 	u8 rsp[64];
 	struct l2cap_chan *chan;
 	int len, err = 0;

 	if (cmd_len < sizeof(*req))
 		return -EPROTO;

 	dcid  = __le16_to_cpu(req->dcid);
 	flags = __le16_to_cpu(req->flags);

 	BT_DBG("dcid 0x%4.4x flags 0x%2.2x", dcid, flags);

 	chan = l2cap_get_chan_by_scid(conn, dcid);
 	if (!chan) {
 		cmd_reject_invalid_cid(conn, cmd->ident, dcid, 0);
 		return 0;
 	}

 	if (chan->state != BT_CONFIG && chan->state != BT_CONNECT2 &&
 	    chan->state != BT_CONNECTED) {
 		cmd_reject_invalid_cid(conn, cmd->ident, chan->scid,
 				       chan->dcid);
 		goto unlock;
 	}

 	/* Reject if config buffer is too small. */
 	len = cmd_len - sizeof(*req);
 	if (chan->conf_len + len > sizeof(chan->conf_req)) {
 		l2cap_send_cmd(conn, cmd->ident, L2CAP_CONF_RSP,
 			       l2cap_build_conf_rsp(chan, rsp,
 			       L2CAP_CONF_REJECT, flags), rsp);
 		goto unlock;
 	}

 	/* Store config. */
 	memcpy(chan->conf_req + chan->conf_len, req->data, len);
 	chan->conf_len += len;

 	if (flags & L2CAP_CONF_FLAG_CONTINUATION) {
 		/* Incomplete config. Send empty response. */
 		l2cap_send_cmd(conn, cmd->ident, L2CAP_CONF_RSP,
 			       l2cap_build_conf_rsp(chan, rsp,
 			       L2CAP_CONF_SUCCESS, flags), rsp);
 		goto unlock;
 	}

 	/* Complete config. */
 	len = l2cap_parse_conf_req(chan, rsp, sizeof(rsp));
 	if (len < 0) {
 		l2cap_send_disconn_req(chan, ECONNRESET);
 		goto unlock;
 	}

 	chan->ident = cmd->ident;
 	l2cap_send_cmd(conn, cmd->ident, L2CAP_CONF_RSP, len, rsp);
 	if (chan->num_conf_rsp < L2CAP_CONF_MAX_CONF_RSP)
 		chan->num_conf_rsp++;

 	/* Reset config buffer. */
 	chan->conf_len = 0;

 	if (!test_bit(CONF_OUTPUT_DONE, &chan->conf_state))
 		goto unlock;

 	if (test_bit(CONF_INPUT_DONE, &chan->conf_state)) {
 		set_default_fcs(chan);

-		if (chan->mode == L2CAP_MODE_ERTM ||
-		    chan->mode == L2CAP_MODE_STREAMING)
-			err = l2cap_ertm_init(chan);
+		if (chan->state != BT_CONNECTED) {
+			if (chan->mode == L2CAP_MODE_ERTM ||
+			    chan->mode == L2CAP_MODE_STREAMING)
+				err = l2cap_ertm_init(chan);

-		if (err < 0)
-			l2cap_send_disconn_req(chan, -err);
-		else
-			l2cap_chan_ready(chan);
+			if (err < 0)
+				l2cap_send_disconn_req(chan, -err);
+			else
+				l2cap_chan_ready(chan);
+		}

 		goto unlock;
 	}

 	if (!test_and_set_bit(CONF_REQ_SENT, &chan->conf_state)) {
 		u8 buf[64];
 		l2cap_send_cmd(conn, l2cap_get_ident(conn), L2CAP_CONF_REQ,
 			       l2cap_build_conf_req(chan, buf, sizeof(buf)), buf);
 		chan->num_conf_req++;
 	}

 	/* Got Conf Rsp PENDING from remote side and assume we sent
 	   Conf Rsp PENDING in the code above */
 	if (test_bit(CONF_REM_CONF_PEND, &chan->conf_state) &&
 	    test_bit(CONF_LOC_CONF_PEND, &chan->conf_state)) {

 		/* check compatibility */

 		/* Send rsp for BR/EDR channel */
 		l2cap_send_efs_conf_rsp(chan, rsp, cmd->ident, flags);
 	}

 unlock:
 	l2cap_chan_unlock(chan);
 	l2cap_chan_put(chan);
 	return err;
 }



